export const CONTROL_AGENTS = { dot: 'Dot 1', scout: 'Dot 2', forge: 'Dot 3', flux: 'Dot 4', lens: 'Legacy agent' };
export const STAGES = ['intake', 'research', 'plan_review', 'build', 'human_review', 'ready'];
export const STAGE_LABELS = {intake:'Not started',research:'Research',plan_review:'Plan approval',build:'Build',human_review:'Final approval',ready:'Ready for production'};
export const INSIGHT_TYPES = ['task_summary','classification','activity_digest','portfolio_summary','risk_review','propose_tasks','conversation'];
