function invalidate(t){t.planApproval=null;t.review=null;t.finalApproval=null;t.stage='research';release(t);}
function projectAccess(s,p,id){const project=entity(s,'projects',id);check(project,'PROJECT_NOT_FOUND','Project not found.',404);if(p.agent)check(project.owner===p.actor&&!project.recoveryRequired,'PROJECT_NOT_OWNED','This project belongs to another agent or needs assignment.',403);return project;}
function projectWrite(s,p,id,c,{active=true}={}){const project=projectAccess(s,p,id);if(p.agent)check(c.projectFence===project.ownershipFence,'STALE_PROJECT_FENCE','Project assignment changed. Stop and refresh.');if(active)check(project.status==='active','PROJECT_COMPLETED','Reopen the project before changing work.');return project;}
function lease(s,t,p,c,now){projectWrite(s,p,t.projectId,c);check(live(s,t,now)&&t.lease.actor===p.actor,'LEASE_REQUIRED','Claim the task and renew its execution lease.');check(c.fence===t.fence,'STALE_FENCE','Task lease changed. Stop and refresh.');}
