function taskInput(s,input,existing){check(input&&typeof input==='object','INVALID_INPUT','Task details required.',400);const value={title:str(input.title,'Title',160,3),description:str(input.description||'','Description',12000,0),component:str(input.component||'general','Component',180),environment:str(input.environment||'Development','Environment',120),priority:input.priority||'Normal',projectId:input.projectId||'relay',type:input.type||'Task'};check(['Urgent','High','Normal','Low'].includes(value.priority)&&['Feature','Bug','Task','Question'].includes(value.type),'INVALID_INPUT','Invalid priority or type.',400);check(entity(s,'projects',value.projectId),'PROJECT_NOT_FOUND','Select a project.',400);value.dependencies=validatedDependencies(s,input.dependencies||[],existing?.id);
  value.featureId=input.featureId||null;value.featureGroup=str(input.featureGroup||'','Feature group',80,0);value.layer=str(input.layer||'','Layer',80,0);
  if(value.featureId){const feature=entity(s,'tasks',value.featureId);check(feature&&feature.id!==existing?.id&&feature.type==='Feature'&&!feature.featureId&&feature.projectId===value.projectId&&value.type!=='Feature','INVALID_FEATURE','Select a feature in this project. Features cannot be nested.',400);}
  if(existing&&s.tasks.some(t=>t.featureId===existing.id))check(value.type==='Feature'&&value.projectId===existing.projectId,'FEATURE_HAS_TASKS','Move attached tasks before changing the feature type or project.');
  return value;}
function wake(s,recipient,reason,target,now,cause){if(!CONTROL_AGENTS[recipient])return;const id=`${cause}:${recipient}`;if(entity(s,'wakes',id))return;const project=target.projectId?entity(s,'projects',target.projectId):null;s.wakes.push({id,recipient,reason,target,projectFence:project?.ownershipFence??null,status:'pending',attempts:0,nextAt:now,at:iso(now),acknowledgedAt:null,slackId:crypto.randomUUID()});}
function wakeProject(s,id,reason,target,now,cause){const project=entity(s,'projects',id);if(!project||project.recoveryRequired)return;const recipients=project.owner?[project.owner]:s.agents.filter(a=>!a.paused).map(a=>a.id);for(const recipient of recipients)wake(s,recipient,reason,{...target,projectId:id},now,cause);}
export function currentWake(s,w){if(w.status==='cancelled')return false;const id=w.target?.projectId||(w.target?.taskId?entity(s,'tasks',w.target.taskId)?.projectId:null);if(id){const p=entity(s,'projects',id);if(!p||p.recoveryRequired||p.ownershipFence!==w.projectFence||(p.owner&&p.owner!==w.recipient))return false;}if(w.target?.jobId){const j=entity(s,'jobs',w.target.jobId);if(!j||j.status==='complete'||(j.owner&&j.owner!==w.recipient))return false;}return true;}
function cancelWakes(s,id){ /* Assignment fences invalidate pending delivery without rewriting the outbox. */ }
function refreshRecipients(s,project){ /* Project recipients and stale execution are derived from current assignment. */ }
function setOwner(s,project,target,p,reason,now,cause){const from=project.owner;project.owner=target;project.ownershipFence++;project.version++;project.recoveryRequired=false;project.assignedAt=target?iso(now):null;event(s,p,'project_assignment',`${from||'Unassigned'} → ${target||'Unassigned'}: ${reason}`,now,null,{projectId:project.id,previousOwner:from,owner:target,ownershipFence:project.ownershipFence});wakeProject(s,project.id,'project-assigned',{},now,cause);}
