export function initialControl(ownerId,legacy,now){const s=Object.fromEntries(kinds.map(kind=>[kind,[]]));s.meta={ownerId,epoch:crypto.randomUUID(),revision:1,createdAt:now};s.projects.push(newProject('relay','Workspace','Task management and project planning',now));for(const [id,name]of Object.entries(CONTROL_AGENTS))s.agents.push({id,name,paused:false,lastHeartbeat:null,currentAction:null});s.settings.push({id:'integrations',slackEnabled:false,channel:'',mentions:{}});const human={actor:'human',role:'human'};for(const old of legacy?.state?.tasks||[]){const t=newTask(s,{...old,dependencies:[],projectId:'relay'},human,now);t.id=old.id;t.synthetic=!!old.synthetic;t.legacy=structuredClone(old);t.blocker=old.blocker||null;s.events.pop();event(s,human,'imported','Imported task. Fresh approvals required.',now,t,{synthetic:t.synthetic});}for(const old of legacy?.state?.tasks||[])entity(s,'tasks',old.id).dependencies=(old.dependencies||[]).filter(id=>entity(s,'tasks',id));for(const old of legacy?.state?.messages||[])s.messages.push({...old,id:`legacy:${old.id}`,imported:true,room:old.channel,recipients:[],receipts:[]});return s;}
export function controlPrincipal(s,identity){if(identity?.kind==='agent'&&CONTROL_AGENTS[identity.actor])return {actor:identity.actor,role:'agent',subject:identity.subject,agent:true};check(identity?.subject===s.meta.ownerId,'FORBIDDEN','Only the owner or an authenticated agent may access Relay.',403);return {actor:'human',role:'human',subject:identity.subject,agent:false};}
export function messageRecipients(s,m){return m.actor==='human'&&m.projectId?(entity(s,'projects',m.projectId)?.owner?[entity(s,'projects',m.projectId).owner]:[]):m.recipients||[];}
export function messageRoom(s,m){return m.projectId&&m.room?.startsWith('direct:')&&entity(s,'projects',m.projectId)?.owner?`direct:${entity(s,'projects',m.projectId).owner}`:m.room;}
