 for(const part of c.content){check(part&&typeof part==='object','INVALID_MESSAGE_CONTENT','Invalid message segment.',400);if(part.type==='text'){check(typeof part.text==='string'&&part.text.length<=12000,'INVALID_MESSAGE_CONTENT','Text segment is too long.',400);if(part.text)content.push({type:'text',text:part.text});}else{check(part.type==='reference'&&['project','task','feature','file','relationship'].includes(part.referenceType)&&typeof part.id==='string'&&part.id.length>0&&part.id.length<=8192,'INVALID_MESSAGE_CONTENT','Use an explicit reference type and ID.',400);content.push({type:'reference',referenceType:part.referenceType,id:part.id});if(!requested.some(r=>r.type===part.referenceType&&r.id===part.id))requested.push({type:part.referenceType,id:part.id});}}
