function invalidateDependents(s,t,p,now){const affected=new Set([t.id]);let more=true;while(more){more=false;for(const child of s.tasks)if(!affected.has(child.id)&&child.dependencies.some(id=>affected.has(id))){affected.add(child.id);invalidate(child);child.scopeRevision++;child.version++;child.updatedAt=iso(now);event(s,p,'dependency_changed',`Dependency ${t.id} changed; approvals revoked.`,now,child);wakeProject(s,child.projectId,'dependency-changed',{taskId:child.id},now,`dependency:${crypto.randomUUID()}`);more=true;}}}
